# <<< STATIC

# >>> CHOICES
if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_flatpak_app() {
    flatpak list --app --columns=application 2>/dev/null
}

_choice_flatpak_arch() {
    flatpak --supported-arches 2>/dev/null
}

_choice_flatpak_branch() {
    flatpak list --columns=branch 2>/dev/null
}

_choice_flatpak_config_key() {
    flatpak config --list 2>/dev/null | sed -n 's/:.*//p'
}

_choice_flatpak_dbus_session() {
    command -v busctl >/dev/null 2>&1 || return 0
    busctl --user list --acquired --no-legend 2>/dev/null | gawk '$1 !~ /^:/ { print $1 }'
}

_choice_flatpak_dbus_system() {
    command -v busctl >/dev/null 2>&1 || return 0
    busctl --system list --acquired --no-legend 2>/dev/null | gawk '$1 !~ /^:/ { print $1 }'
}

_choice_flatpak_device() {
    printf '%s\n' dri usb input kvm shm all
}

_choice_flatpak_dir() {
    _argc_util_comp_path dir
}

_choice_flatpak_doc_id() {
    flatpak documents --columns=id 2>/dev/null
}

_choice_flatpak_env_assignment() {
    compgen -e | while IFS= read -r name; do
        printf '%s=\0\n' "$name"
    done
}

_choice_flatpak_env_var() {
    compgen -e
}

_choice_flatpak_feature() {
    printf '%s\n' devel multiarch bluetooth
}

_choice_flatpak_file() {
    _argc_util_comp_path
}

_choice_flatpak_filesystem() {
    printf '%s\n' home host host-os host-etc xdg-desktop xdg-documents xdg-download xdg-music xdg-pictures xdg-public-share xdg-templates xdg-videos xdg-run xdg-config xdg-cache xdg-data
    _argc_util_comp_path
}

_choice_flatpak_gpg_key() {
    command -v gpg >/dev/null 2>&1 || return 0
    gpg --list-keys --with-colons 2>/dev/null | gawk -F: '$1 == "fpr" { print $10 }'
}

_choice_flatpak_install_location() {
    _choice_flatpak_remote
    _argc_util_comp_path exts=.flatpakref,.flatpakrepo
}

_choice_flatpak_instance() {
    flatpak ps --columns=instance 2>/dev/null
}

_choice_flatpak_permission_id() {
    local table="${argc_TABLE:-${argc_table:-}}"
    [[ -n "$table" ]] || return 0
    flatpak permissions "$table" 2>/dev/null | gawk 'NR > 1 { print $2 }'
}

_choice_flatpak_permission_table() {
    flatpak permissions 2>/dev/null | gawk 'NR > 1 { print $1 }'
}

_choice_flatpak_persist() {
    _argc_util_comp_path dir "cd=${HOME:-}"
}

_choice_flatpak_ref() {
    flatpak list --columns=ref 2>/dev/null
}

_choice_flatpak_remote() {
    flatpak remotes --columns=name 2>/dev/null
}

_choice_flatpak_remote_file() {
    _argc_util_comp_path exts=.flatpakrepo
}

_choice_flatpak_remote_ref() {
    local remote="${argc_remote:-}"
    [[ -n "$remote" ]] || return 0
    _argc_util_cache 300 _helper_flatpak_remote_ref "flatpak_remote_ref:$remote"
}

_choice_flatpak_repo_ref() {
    command -v ostree >/dev/null 2>&1 || return 0
    local repo="${argc_location:-${argc_src_repo:-}}"
    [[ -n "$repo" ]] || return 0
    ostree refs --repo="$repo" 2>/dev/null
}

_choice_flatpak_runtime() {
    flatpak list --runtime --columns=application 2>/dev/null
}

_choice_flatpak_runtime_version() {
    flatpak list --runtime --columns=branch 2>/dev/null
}

_choice_flatpak_share() {
    printf '%s\n' network ipc
}

_choice_flatpak_socket() {
    printf '%s\n' x11 wayland fallback-x11 pulseaudio system-bus session-bus ssh-auth pcsc cups gpg-agent inherit-wayland-socket
}

_choice_flatpak_usb() {
    command -v lsusb >/dev/null 2>&1 || return 0
    lsusb 2>/dev/null | sed -n 's/^Bus [0-9][0-9]* Device [0-9][0-9]*: ID \([0-9A-Fa-f][0-9A-Fa-f]*:[0-9A-Fa-f][0-9A-Fa-f]*\).*/\1/p'
}

_helper_flatpak_remote_ref() {
    flatpak remote-ls --columns=ref "$argc_remote" 2>/dev/null
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
